def apply_confidence_threshold(response, threshold=0.75):
    # Get the confidence score from the response
    confidence = response.get('intents', [{}])[0].get('confidence', 0)

    # Check if the confidence score is below the threshold
    if confidence < threshold:
        return 'escalate'

    # If confidence is sufficient, return 'send'
    return 'send'

