def produce_deflection_report(resolved_count, escalated_count):
    report = {
        'resolved': resolved_count,
        'escalated': escalated_count,
        'deflection_rate': resolved_count / (resolved_count + escalated_count) * 100 if (resolved_count + escalated_count) > 0 else 0
    }
    return report

