import os
import json
import urllib.request


def generate_answer(user_message):
    url = 'https://api.openai.com/v1/chat/completions'
    headers = {
        'Authorization': f'Bearer {os.environ.get("OPENAI_API_KEY")}',
        'Content-Type': 'application/json'
    }
    payload = json.dumps({
        'model': 'gpt-4o',
        'messages': [
            {'role': 'system', 'content': 'You are a helpful assistant.'},
            {'role': 'user', 'content': user_message}
        ]
    }).encode('utf-8')
    request = urllib.request.Request(url, data=payload, headers=headers)
    response = urllib.request.urlopen(request)
    return json.loads(response.read().decode('utf-8')).get('choices', [{}])[0].get('message', {}).get('content', '')

answer = generate_answer('What is the weather today?')

import json
import urllib.request
import os


def log_conversation(chat_id, question, answer):
    url = f'{os.environ.get("SUPABASE_URL")}/rest/v1/conversations'
    headers = {
        'apikey': os.environ.get("SUPABASE_KEY"),
        'Authorization': f'Bearer {os.environ.get("SUPABASE_KEY")}',
        'Content-Type': 'application/json',
        'Prefer': 'return=representation'
    }
    payload = json.dumps({
        'chat_id': chat_id,
        'question': question,
        'answer': answer
    }).encode('utf-8')
    request = urllib.request.Request(url, data=payload, headers=headers)
    response = urllib.request.urlopen(request)
    if response.status not in (200, 201, 204):
        raise Exception('Failed to log conversation')
    return response.read().decode('utf-8')

log_response = log_conversation(987654321, 'What is the weather today?', 'The weather today is sunny with a high of 75°F.')
